 "content": "def transform(grid):
    """Colored pluses send rays; empty pluses cast full blank row/column bands.

    Colored rays pass their own adjacent 3 arm and stop at the next 3 marker.
    Empty-center pluses erase along their entire row and column (except 3s),
    overlaying the colored rays. The 3 markers themselves are preserved.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r-1][c] == 3 and grid[r+1][c] == 3
                    and grid[r][c-1] == 3 and grid[r][c+1] == 3):
                centers.append((r, c, grid[r][c]))

    # Draw nonzero colored-center rays.
    for r, c, color in centers:
        if color in (0, 3):
            continue
        for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            y, x, distance = r + dr, c + dc, 1
            while 0 <= y < h and 0 <= x < w:
                if distance > 1 and grid[y][x] == 3:
                    break
                if grid[y][x] != 3:
                    out[y][x] = color
                y += dr
                x += dc
                distance += 1

    # Empty-center crosses produce full blank lines, which overwrite strokes.
    for r, c, color in centers:
        if color != 0:
            continue
        for x in range(w):
            if grid[r][x] != 3:
                out[r][x] = 0
        for y in range(h):
            if grid[y][c] != 3:
                out[y][c] = 0
    return out
